window.RP_SESSION={"id":"S-30de8f2f870d","messages":[{"id":"RP-III-0049707","time":"2026-03-20T14:28:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"@Maria Anaïs Ésther","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049708","time":"2026-03-20T14:29:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"훈련장 모퉁이, 소란을 잠시 뒤로 하고 포말하우트는 자리에 앉았다. \n\n자신의 옆자리는 깨끗한 수건을 깔아주고 철제통을 꺼내서 컵이 향긋한 꽃향기가 나는 것을 체운다.\n\n\" 라일락 꽃차에요 마리아씨. '","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049709","time":"2026-03-20T14:30:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 일단 드세요 \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049710","time":"2026-03-20T14:32:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㅇ어...네..\"\n\n따끈한 찻잔 들어 호록.. 들이켰습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049711","time":"2026-03-20T14:32:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..그, ...ㅇ아니에요\"\n\n시선 빙글 돌려 바닥 내려다보았습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049712","time":"2026-03-20T14:33:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 훗... 사과하실 필요 없어요 마리아씨. 제가 그때 너무 감정적 이었습니다. \" \n\n마리아를 바라보며 빙긋 미소를 짓고 자신도 꽃차를 마시면서 말을 한다.\n\n \" 당신도 당신 나름대로 표현 한 것 뿐이니까요. 내 믿음이 그렇다고 해서, 타인을 강제할 것은 아니죠. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049713","time":"2026-03-20T14:34:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 라운데라님을 사칭, 표현이 과격하지만 결국엔 당신은 신성력을 사용하는 사제가 아닙니까. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049714","time":"2026-03-20T14:34:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ...그거면 된거죠. 화내서 미안합니다 마리아씨. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049715","time":"2026-03-20T14:34:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"....... 아뇨, 방정맞은 제 입 때문이었습니다\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049716","time":"2026-03-20T14:35:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..어제 선물은,.. 감사했어요\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049717","time":"2026-03-20T14:36:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ....... 네 선물, 아참 선물을 줬죠. 오는 길에 옛 친구를 만나서 술에 입을 댄 뒤로 기억이 잘 없어서요 \" \n\n장난스레 말하며 .. 허수아비를 바라본다. 둘의 말을 듣는 것은 저 허수아비 뿐이었다. \n\n\" 궁금한게 있는데 마리아씨. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049718","time":"2026-03-20T14:36:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 여쭈어 보아도 될 까요. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049719","time":"2026-03-20T15:06:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..네, 뭐든지요.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049720","time":"2026-03-20T15:14:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...최선을 다해 답해드리죠\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049721","time":"2026-03-20T15:15:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ....환대 해주셔서 감사합니다 \"\n\n잠시 허수아비를 바라본다. 상처 입은 저 허수아비는 말을 잊어버렸다. 표정 또한 없었다\n\n\" 당신이 모시는 신의 이름은 무엇입니까. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049722","time":"2026-03-20T15:15:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\".....\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049723","time":"2026-03-20T15:16:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..ㅁ모른다고... ㅁ,..말..말씀 드렸잖습니까....\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049724","time":"2026-03-20T15:18:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ....... 마리아씨 \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049725","time":"2026-03-20T15:19:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 제가 어제 모닥불에서 이야기 드렸죠. 임무 때문에 어촌과 과수원에 다녀왔다고요. '","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049726","time":"2026-03-20T15:19:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..........하지만...하지만,.....\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049727","time":"2026-03-20T15:19:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" .... 북쪽에 뜬 별이 남쪽에 추락했다는 말 까지. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049728","time":"2026-03-20T15:19:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ...말씀해주세요. 당신이 모시는 신의.이름 조차 말할 수 없다면 그건 신이 아닐테죠. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049729","time":"2026-03-20T15:20:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 아니면..제가 먼저 이야기 드리겠습니다. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049730","time":"2026-03-20T15:20:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"....무슨.. 말씀이신가요...\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049731","time":"2026-03-20T15:20:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ...라운데라님을 '사칭' 한다는 말을 못내 잊어버리지 못하고 여러가지 조사를 했습니다. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049732","time":"2026-03-20T15:21:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ...어느 사전에서든 라운데라님을 사칭한 신을 모시는 사제가 신성력을 사용 한다는 것은 못봤으니까요. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049733","time":"2026-03-20T15:22:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n\"샤덴프로이데십니다.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049734","time":"2026-03-20T15:24:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ...네 저는 그 이름을 .. 어느 과수원에 세워져 있는 낡은 성당에서 찾았습니다. \"\n\n\" 전 몇칠간 분주히 도서관을 뒤지고 고문헌을 보면서 샤덴프로이데라는 존재를 찾았습니다. \"\n\n\" 여러 추적결과 ..그것을 모시는, 다른 그러니까..또다른 신앙은 없더라고요.","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049735","time":"2026-03-20T15:24:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 신앙이 아니라 ㅡ 마치 그 신은... 자신을 믿는 것 보다는 다른 자들의 희로애락을 보는 것을 즐기는 것 같더라고요. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049736","time":"2026-03-20T15:25:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ..신자가 아니라, 연기자를 모으는 느낌... \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049737","time":"2026-03-20T15:26:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049738","time":"2026-03-20T15:26:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"그리 말하지 마시죠..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049739","time":"2026-03-20T15:27:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" .... 이로써 당신과 저는 똑같아졌습니다 \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049740","time":"2026-03-20T15:27:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 서로의 신앙을 부정했으니까요 \" \n\n웃음을 짓는다.","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049741","time":"2026-03-20T15:27:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"......\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049742","time":"2026-03-20T15:27:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 제가 하고 싶은 말은 당신을 곤란하게 해드리고 싶어서 그런 것이 아니에요. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049743","time":"2026-03-20T15:28:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 아니 여러 의문이 있습니다만.. 샤덴프로이데는 라운데라님을.사칭하고도 어떻게 살아남아서 자신을 믿는 신도들에게 신성력을 나누어주는가. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049744","time":"2026-03-20T15:28:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ..또, 샤덴프로이데를 믿는 것은 당신 뿐인가. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049745","time":"2026-03-20T15:28:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 여러 의문이 있지만 말하지 않을게요. 다만","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049746","time":"2026-03-20T15:29:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ...난 당신이 걱정되서 하는 말이에요 기억나세요? 북쪽의 별이 남쪽으로 떨어졌다는 말. '","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049747","time":"2026-03-20T15:30:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...기억합니다..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049748","time":"2026-03-20T15:32:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" .... 제가, 과수원의 성당에 들어서서  샤덴프로이데에 대한 기록이 적힌 책을 열어본 순간. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049749","time":"2026-03-20T15:32:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ... 어떠한 계시가 떠올랐습니다. 그 즉시 북쪽에서 남쪽으로 별똥별이 떨어졌고. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049750","time":"2026-03-20T15:33:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ..그 계시는 시작되었음을 알리는 종소리와 함께 성당을 지키던 사제는 온데간데 사라졌습니다. \" \n\n\" 이는 .. 필시 불길한 증세입니다. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049751","time":"2026-03-20T15:33:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ... 스텔라에게는 이미 보고를 끝났고 이렇게 조용히 당신만 불러서 따로 이야기 하는 것 입니다 \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049752","time":"2026-03-20T15:34:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..아뇨 그분은 그런분이 아니십니다.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049753","time":"2026-03-20T15:34:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" .. 그 계시는... 죄송합니다. 강력한 신성력에 의해 기억이 나지 않군요 \" \n\n이내 마리아의 말을 듣고 고개를 끄덕인 뒤 허수아비를 바라본다\n\n\" 아니시겠죠 \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049754","time":"2026-03-20T15:35:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 제가 모시는 라운데라님도 그런 분이 아니십니다. 사칭 당할 분도 아니시라는 말씀입니다. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049755","time":"2026-03-20T15:35:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 단지 내가 하고 싶은 말은... 당신에게 위험한 일이 생길 것 같아 말을 한 것 뿐입니다. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049756","time":"2026-03-20T15:35:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ..저보다는 당신이 잘알겠죠 샤덴프로이데님을. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049757","time":"2026-03-20T15:38:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\".........................\"\n\n\"그럴일은 없을겁니다. ..그분께서 제게 그러실리가 없잖습니까?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049758","time":"2026-03-20T15:40:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"자애로우신분입니다. ......분명합니다.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049759","time":"2026-03-20T15:42:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"차는.. 감사했습니다.\"\n\n\".....만약 그분께서 그리 하신다면 ..아뇨 그럴일은 없습니다.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049760","time":"2026-03-20T15:43:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" .... 한번 찾아가시는 것이 좋을 것 같습니다 '사제님' \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049761","time":"2026-03-20T15:43:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"......\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049762","time":"2026-03-20T15:43:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\".........언젠가요.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049763","time":"2026-03-20T15:44:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"제 두 손 꽉 붙들곤 급하게 자리를 떴습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0049764","time":"2026-03-20T15:44:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" 시간이.그렇게 많지 않아요. 남쪽의 림턴 빌리지로 향하세요. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049765","time":"2026-03-20T15:44:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"\" ... 후우 \" \n\n이내 마리아가 떠난 걸 보고 한숨을 쉰 뒤 관자놀이를 누른다\n\n\" ....나도 이렇게 까지 궁금해 하고 싶지 않았다고. \"","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049766","time":"2026-03-20T15:45:00+09:00","room":"RP III","name":"포말하우트","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3ab8153acc27"]},{"id":"RP-III-0049767","time":"2026-03-20T15:45:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]},{"id":"RP-III-0049768","time":"2026-03-20T17:35:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"unresolved","type":"dialogue","body":"https://youtu.be/ZwpVPJzNaok?si=FajvcQajHhzyfPBv","characters":[]}]};
